import requests
from bs4 import BeautifulSoup

def task_func(url, tag):
    # Check if the provided tag is a valid HTML tag
    valid_tags = {'div', 'p', 'span', 'a', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'ul', 'ol', 'li', 'table', 'tr', 'td', 'th'}
    if tag not in valid_tags:
        return None

    try:
        # Send a GET request to the provided URL
        response = requests.get(url)
        response.raise_for_status()  # Raise an exception for 4xx or 5xx status codes

        # Parse the HTML content using BeautifulSoup
        soup = BeautifulSoup(response.text, 'html.parser')

        # Find the first occurrence of the specified HTML tag
        first_tag = soup.find(tag)

        # Extract the text content of the tag, strip whitespace, and return it
        if first_tag:
            return first_tag.get_text(strip=True)
        else:
            return None

    except requests.RequestException as e:
        # Handle network errors gracefully
        print(f"Network error occurred: {e}")
        return None
