import numpy as np
from functools import reduce

def task_func(list_of_pairs):
    if not isinstance(list_of_pairs, list) or not all(isinstance(pair, tuple) for pair in list_of_pairs):
        raise TypeError("Input must be a list of tuples.")

    if not list_of_pairs:
        return np.array([1])

    second_values = np.array([pair[1] for pair in list_of_pairs])
    product = reduce((lambda x, y: x * y), second_values)

    return np.array([product])

# Unit tests
