            try:
                response = requests.get(api_url)
                response.raise_for_status()  # Raise an exception for 4xx or 5xx status codes
                return jsonify(response.json())
            except requests.exceptions.HTTPError as errh:
                return make_response(jsonify({"error": str(errh)}), 500)
            except requests.exceptions.ConnectionError as errc:
                return make_response(jsonify({"error": "Connection error"}), 500)
            except requests.exceptions.Timeout as errt:
                return make_response(jsonify({"error": "Request timed out"}), 504)
            except requests.exceptions.RequestException as err:
                return make_response(jsonify({"error": "An error occurred"}), 500)

    api.add_resource(ExternalData, '/external_data')

    @app.errorhandler(404)
    def not_found_error(error):
        return make_response(jsonify({"error": "Not found"}), 404)

    @app.errorhandler(500)
    def internal_server_error(error):
        return make_response(jsonify({"error": "Internal server error"}), 500)

