import pandas as pd
from random import randint, seed as random_seed
import statistics
import numpy as np

def task_func(animals=None, seed=42):
    if not animals:
        return pd.DataFrame()

    random_seed(seed)

    # Generate random counts for each animal
    animal_counts = {animal: [randint(1, 100) for _ in range(10)] for animal in animals}

    # Calculate statistics
    mean_counts = {animal: np.mean(counts) for animal, counts in animal_counts.items()}
    median_counts = {animal: np.median(counts) for animal, counts in animal_counts.items()}
    std_dev_counts = {animal: statistics.stdev(counts) for animal, counts in animal_counts.items()}

    # Create DataFrame
    df = pd.DataFrame.from_dict(
        {
            'Animal': list(animal_counts.keys()),
            'Mean': list(mean_counts.values()),
            'Median': list(median_counts.values()),
            'Standard Deviation': list(std_dev_counts.values())
        },
        orient='index'
    )

    # Plot bar chart
    import matplotlib.pyplot as plt
    df.plot(kind='bar', x='Animal', y=['Mean', 'Median', 'Standard Deviation'])
    plt.title('Animal Count Statistics')
    plt.xlabel('Animal')
    plt.ylabel('Statistic')
    plt.show()

    return df

# Unit tests
import unittest

class TestAnimalCountStats(unittest.TestCase):
    def test_mean_calculation(self):
        animals = ['Lion', 'Elephant', 'Giraffe']
        result_df = task_func(animals=animals)
        expected_mean = {
            'Lion': 35.0,
            'Elephant': 35.0,
            'Giraffe': 35.0
        }
        for animal, mean in expected_mean.items():
            self.assertAlmostEqual(result_df.loc[animal, 'Mean'], mean, places=1)

    def test_median_calculation(self):
        animals = ['Tiger', 'Zebra', 'Kangaroo']
        result_df = task_func(animals=animals)
        expected_median = {
            'Tiger': 25.0,
            'Zebra': 25.0,
            'Kangaroo': 25.0
        }
        for animal, median in expected_median.items():
            self.assertAlmostEqual(result_df.loc[animal, 'Median'], median, places=1)

    def test_std_dev_calculation(self):
        animals = ['Hippopotamus', 'Rhinoceros', 'Walrus']
        result_df = task_func(animals=animals)
        expected_std_dev = {
            'Hippopotamus': 14.14,
            'Rhinoceros': 14.14,
            'Walrus': 14.14
        }
        for animal, std_dev in expected_std_dev.items():
            self.assertAlmostEqual(result_df.loc[animal, 'Standard Deviation'], std_dev, places=2)

if __name__ == '__main__':
    unittest.main(argv=[''], verbosity=2, exit=False)
