import pandas as pd
import numpy as np
from random import randint
# Constants
STUDENTS = ['Joe', 'Amy', 'Mark', 'Sara', 'John', 'Emily', 'Zoe', 'Matt']
COURSES = ['Math', 'Physics', 'Chemistry', 'Biology', 'English', 'History', 'Geography', 'Computer Science']

def task_func():
    if not STUDENTS or not COURSES:
        return pd.DataFrame()

    # Generate random grades for each student in each course
    grades_data = {
        student: {course: randint(0, 100) for course in COURSES}
        for student in STUDENTS
    }

    # Calculate average grades
    average_grades = {
        student: round(np.mean([grades_data[student][course] for course in COURSES]), 2)
        for student in STUDENTS
    }

    # Create DataFrame
    df = pd.DataFrame(grades_data).reset_index().rename(columns={'index': 'Student', 0: 'Course'})
    df['Average Grade'] = df['Student'].map(average_grades)

    return df
```

