import json
import urllib.request
import urllib.parse
import gzip

def task_func(url_str, file_path):
    # Validate the URL
    try:
        result = urllib.parse.urlparse(url_str)
        if not all([result.scheme, result.netloc]):
            raise ValueError("Invalid URL: must contain a scheme (http, https) and a network location (domain)")
    except ValueError as e:
        raise ValueError("Invalid URL: " + str(e))

    # Fetch the JSON data
    try:
        with urllib.request.urlopen(url_str) as response:
            json_data = response.read().decode('utf-8')
    except urllib.error.URLError as e:
        raise ValueError(f"HTTP error occurred: {e.reason}")

    # Validate JSON format
    try:
        json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError("Invalid JSON format: " + str(e))

    # Ensure the file path does not already exist
    if os.path.exists(file_path):
        while True:
            new_file_path = input(f"File '{file_path}' already exists. Please enter a new file path: ")
            if not os.path.exists(new_file_path):
                file_path = new_file_path
                break
            print("File path already in use. Please choose a different path.")

    # Compress JSON data into a gzip file
    try:
        with gzip.open(file_path, 'wb') as f_gzip:
            f_gzip.write(json_data.encode('utf-8'))
    except IOError as e:
        raise IOError(f"Error writing to file: {e}")

    return file_path
