import re
import socket

def task_func(ip_addresses: list) -> dict:
    # Define the regex pattern for validating IP addresses
    ip_regex = re.compile(r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$')

    result_dict = {}

    for ip in ip_addresses:
        # Validate the IP address using the regex
        if not ip_regex.match(ip):
            result_dict[ip] = None
            continue

        try:
            # Resolve the IP address to a hostname
            hostname = socket.gethostbyaddr(ip)
            result_dict[ip] = hostname[0] if hostname else None
        except (socket.herror, socket.gaierror):
            result_dict[ip] = None

    return result_dict
