import re
import nltk
from string import punctuation
nltk.download('punkt')

def task_func(df):
    if df.empty:
        raise ValueError("The DataFrame is empty.")

    required_columns = ['Title', 'Content']
    if not all(col in df.columns for col in required_columns):
        raise ValueError("The DataFrame must contain 'Title' and 'Content' columns.")

    keyword_pattern = re.compile(r'\b(like|what)\b', re.IGNORECASE)

    word_freq = {}

    for index, row in df.iterrows():
        title_lower = row['Title'].lower()
        content_lower = row['Content'].lower()

        if not keyword_pattern.search(title_lower):
            continue

        words = nltk.word_tokenize(content_lower)
        words = [word for word in words if word not in punctuation]

        for word in words:
            if word in word_freq:
                word_freq[word] += 1
            else:
                word_freq[word] = 1

    return word_freq
