import random
from scipy import stats

def task_func(animals, mean):
    if not animals:
        return {}

    # Generate the number of customers following a Poisson distribution
    num_customers = stats.poisson.rvs(mean)

    # Initialize sales dictionary
    sales_data = {animal: 0 for animal in animals}

    # Simulate customer purchases
    for _ in range(num_customers):
        customer_purchase = random.choice(animals)
        sales_data[customer_purchase] += 1

    # Display and return the sales summary
    print(f"Sales Summary:")
    for animal, count in sales_data.items():
        print(f"{animal}: {count} sales")

    return sales_data
