import numpy as np
import itertools
import json

def task_func(data_list, json_file_name="mean_values.json"):
    if not data_list:
        return "The input data list is empty. No mean values can be calculated."

    numeric_data = [x for x in data_list if isinstance(x, (int, float))]
    if not numeric_data:
        return "No numeric values found in the input data list."

    means_dict = {}
    for i, group in enumerate(itertools.groupby(numeric_data, key=lambda x: type(x))):
        numeric_values = list(group[1])
        if numeric_values:
            means_dict[f"Position {i}"] = np.mean(numeric_values)

    if json_file_name:
        with open(json_file_name, 'w') as json_file:
            json.dump(means_dict, json_file, indent=4)

