from collections import Counter
import os
import json

def task_func(filename, directory):
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")

    word_counts = Counter()

    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.txt') and os.path.getsize(os.path.join(root, file)) > 0:
                with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                    content = f.read()
                    words = content.split()
                    word_counts.update(words)

    try:
        with open(os.path.join(directory, filename), 'w') as json_file:
            json.dump(dict(word_counts), json_file, indent=4)
    except PermissionError:
        raise PermissionError(f"Permission denied while writing to the JSON file '{filename}'.")

    return sum(word_counts.values())
