import re
import os
import shutil
from datetime import datetime

def task_func(directory):
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory '{directory}' does not exist.")

    file_pattern = re.compile(r'\[([^]]+)\]')
    file_dict = {}
    organized_files = {}

    for filename in os.listdir(directory):
        match = file_pattern.search(filename)
        if match:
            text = match.group(1).strip()
            subdirectory_name = text.replace(" ", "_")
            subdirectory_path = os.path.join(directory, subdirectory_name)

            if not os.path.exists(subdirectory_path):
                os.makedirs(subdirectory_path)

            file_path = os.path.join(directory, filename)
            shutil.move(file_path, subdirectory_path)

            if subdirectory_name not in file_dict:
                file_dict[subdirectory_name] = []
            file_dict[subdirectory_name].append(filename)
            organized_files[subdirectory_name] = file_dict[subdirectory_name]

    return (directory, file_dict)
