import json
import os

def task_func(file_path: str, regex_pattern=r'\(.+?)|\w') -> dict:
    # Validate the input file path
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"The file '{file_path}' does not exist.")

    # Validate the file as a JSON file
    try:
        with open(file_path, 'r') as file:
            json_data = json.load(file)
    except json.JSONDecodeError:
        raise ValueError(f"The file '{file_path}' is not a valid JSON file.")

    # Extract matches using the provided regex pattern
    matches = []
    for key, value in json_data.items():
        if isinstance(value, str):
            matches.extend(re.findall(regex_pattern, value))
        elif isinstance(value, dict):
            matches.extend(task_func(value, regex_pattern).get(key, []))

    # Return the result as a dictionary
    return {file_path: matches}
