import subprocess
import os
import sys
import time

def task_func(script_path, wait=True, *args):
    if not os.path.isfile(script_path):
        raise ValueError(f"The script at path '{script_path}' does not exist.")

    try:
        process = subprocess.Popen([script_path] + list(args), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if wait:
            process.wait()
        else:
            return None

        return_code = process.returncode

        if return_code != 0:
            raise subprocess.CalledProcessError(return_code, [script_path] + list(args))

        return return_code

    except subprocess.CalledProcessError as e:
        raise e

    except Exception as e:
        raise ValueError(f"An error occurred while running the script: {e}")

# Example usage:
