import subprocess
import os
import signal
import time

def task_func(process_name: str) -> int:
    # Validate the input process name to prevent command injection
    if not isinstance(process_name, str) or not process_name:
        raise ValueError("Process name must be a non-empty string.")

    # List all running processes
    try:
        output = subprocess.check_output(['ps', 'aux']).decode('utf-8')
    except Exception as e:
        print(f"Error fetching process list: {e}")
        return 0

    # Filter processes by name and count them
    process_list = output.split('\n')
    process_count = 0
    for line in process_list:
        if line.startswith(process_name):
            process_count += 1

    # Send termination signal to each matching process
    if process_count > 0:
        for line in process_list:
            if line.startswith(process_name):
                try:
                    pid = int(line.split()[0])
                    os.kill(pid, signal.SIGTERM)
                    print(f"Sent SIGTERM to process {pid}")
                except (IndexError, ValueError):
                    print(f"Skipping process {line} as it doesn't have a valid PID.")

        # Wait for 1 second for processes to terminate
        time.sleep(1)

        # Check if any processes have terminated
        terminated_processes = [line for line in process_list if line.startswith(process_name) and not os.path.exists(line)]
        if terminated_processes:
            print(f"Terminated {len(terminated_processes)} processes.")
        else:
            print("All processes with the given name have not terminated within the specified time.")

    return process_count
