import pandas as pd
import os

def task_func(original_file_location="test.xlsx", new_file_location="new_test.xlsx", sheet_name="Sheet1"):
    # Check if the original file exists
    if not os.path.isfile(original_file_location):
        raise FileNotFoundError(f"The file {original_file_location} does not exist.")

    # Read the original file and ensure the specified sheet exists
    try:
        original_data = pd.read_excel(original_file_location, sheet_name=sheet_name)
    except KeyError:
        raise ValueError(f"The sheet '{sheet_name}' does not exist in the file {original_file_location}.")

    # Write the data to a new file
    new_data = original_data.copy()
    new_data.to_excel(new_file_location, index=False)

    # Read the new file and return the DataFrame
    return pd.read_excel(new_file_location)

